<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Maze Discovery Bots</title>
<style>
  :root {
    color-scheme: dark;
    --panel: #172033;
    --ink: #eaf2ff;
    --muted: #afbdd4;
    --accent: #72d6ff;
  }

  * { box-sizing: border-box; }

  body {
    margin: 0;
    min-height: 100vh;
    background: linear-gradient(145deg, #09111d, #15243d);
    color: var(--ink);
    font-family: Arial, Helvetica, sans-serif;
    display: grid;
    place-items: center;
    padding: 18px;
  }

  main {
    width: min(760px, 100%);
    background: rgba(23, 32, 51, 0.94);
    border: 1px solid #3e5578;
    border-radius: 16px;
    box-shadow: 0 18px 60px #0008;
    padding: 18px;
  }

  h1 {
    margin: 0 0 8px;
    text-align: center;
    font-size: clamp(1.3rem, 3vw, 2rem);
    letter-spacing: .04em;
  }

  .description {
    margin: 0 auto 15px;
    text-align: center;
    color: var(--muted);
    max-width: 670px;
    font-size: .92rem;
    line-height: 1.4;
  }

  .hud {
    display: flex;
    gap: 12px;
    align-items: center;
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: 14px;
  }

  .stat {
    border: 1px solid #435c83;
    background: #0d1728;
    border-radius: 8px;
    padding: 8px 12px;
    min-width: 145px;
    text-align: center;
    font-weight: bold;
  }

  button {
    cursor: pointer;
    border: 1px solid #8bd8ff;
    border-radius: 8px;
    padding: 9px 16px;
    color: #07121f;
    background: #8bd8ff;
    font-weight: bold;
    transition: transform .15s, background .15s;
  }

  button:hover {
    background: #c4edff;
    transform: translateY(-1px);
  }

  #maze {
    width: 100%;
    display: grid;
    place-items: center;
    overflow: auto;
    background: #07101c;
    border: 1px solid #3e5578;
    border-radius: 10px;
    padding: 8px;
  }

  canvas {
    display: block;
    width: min(630px, 100%);
    height: auto;
    background: #f5f8ff;
    border-radius: 3px;
  }

  .legend {
    margin: 11px 0 0;
    text-align: center;
    color: var(--muted);
    font-size: .82rem;
  }

  .swatch {
    display: inline-block;
    width: 11px;
    height: 11px;
    vertical-align: -1px;
    border-radius: 50%;
    background: #9d7cff;
    margin: 0 3px 0 8px;
  }

  .exit-swatch {
    background: #23b967;
    border-radius: 2px;
  }
</style>
</head>
<body>
<main>
  <h1>Maze Discovery Bots</h1>
  <p class="description">
    Twenty-four bots independently discover this perfect maze. Each remembers only
    passages it has personally entered and uses DFS/Tremaux-style backtracking.
  </p>

  <div class="hud">
    <div class="stat" id="completed">Completed: 0 / 24</div>
    <div class="stat" id="timer">Timer: 0 ticks</div>
    <button id="reset" type="button">New Maze</button>
  </div>

  <div id="maze" aria-label="Randomly generated maze"></div>

  <p class="legend">
    <span class="swatch"></span>Bots
    <span class="swatch exit-swatch"></span>Exit
  </p>
</main>

<script>
(function () {
  "use strict";

  const ROWS = 21;
  const COLS = 21;
  const BOT_COUNT = 24;
  const CELL = 30;
  const TICK_MS = 110;

  const mazeElement = document.getElementById("maze");
  const completedElement = document.getElementById("completed");
  const timerElement = document.getElementById("timer");
  const resetButton = document.getElementById("reset");

  const canvas = document.createElement("canvas");
  canvas.width = COLS * CELL;
  canvas.height = ROWS * CELL;
  canvas.setAttribute("role", "img");
  canvas.setAttribute("aria-label", "A maze with exploring bots");
  mazeElement.appendChild(canvas);

  const ctx = canvas.getContext("2d");

  const DIRECTIONS = [
    { name: "n", dr: -1, dc: 0, opposite: "s" },
    { name: "e", dr: 0, dc: 1, opposite: "w" },
    { name: "s", dr: 1, dc: 0, opposite: "n" },
    { name: "w", dr: 0, dc: -1, opposite: "e" }
  ];

  function key(r, c) {
    return r + "," + c;
  }

  function makeRandom(seed) {
    let state = (seed >>> 0) || 0x9e3779b9;
    return function random() {
      state ^= state << 13;
      state ^= state >>> 17;
      state ^= state << 5;
      return ((state >>> 0) / 4294967296);
    };
  }

  function shuffled(array, random) {
    const copy = array.slice();
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(random() * (i + 1));
      const temp = copy[i];
      copy[i] = copy[j];
      copy[j] = temp;
    }
    return copy;
  }

  function allDirectionOrders() {
    const source = ["n", "e", "s", "w"];
    const output = [];

    function build(prefix, remaining) {
      if (remaining.length === 0) {
        output.push(prefix);
        return;
      }
      for (let i = 0; i < remaining.length; i++) {
        build(
          prefix.concat(remaining[i]),
          remaining.slice(0, i).concat(remaining.slice(i + 1))
        );
      }
    }

    build([], source);
    return output;
  }

  const GAME = {
    elapsed: 0,
    size: { rows: ROWS, cols: COLS },
    spawn: { r: 0, c: 0 },
    exit: { r: ROWS - 1, c: COLS - 1 },
    bots: [],
    tick: tick,
    reset: reset,
    walls: wallsAt
  };

  let grid = [];
  let activeSeed = 0;
  let lastFrameTime = performance.now();

  function normalizeSeed(seed) {
    if (typeof seed === "number" && Number.isFinite(seed)) {
      return Math.floor(seed) >>> 0;
    }
    const timePart = Date.now() >>> 0;
    const extraPart = Math.floor(Math.random() * 4294967295) >>> 0;
    return (timePart ^ extraPart ^ 0xa5a5f00d) >>> 0;
  }

  function makeGrid() {
    const made = [];
    for (let r = 0; r < ROWS; r++) {
      const row = [];
      for (let c = 0; c < COLS; c++) {
        row.push({ n: true, e: true, s: true, w: true });
      }
      made.push(row);
    }
    return made;
  }

  function generatePerfectMaze(random) {
    grid = makeGrid();

    const visited = new Set();
    const stack = [{ r: GAME.spawn.r, c: GAME.spawn.c }];
    visited.add(key(GAME.spawn.r, GAME.spawn.c));

    while (stack.length > 0) {
      const current = stack[stack.length - 1];
      const choices = [];

      for (const direction of DIRECTIONS) {
        const nr = current.r + direction.dr;
        const nc = current.c + direction.dc;
        if (
          nr >= 0 && nr < ROWS &&
          nc >= 0 && nc < COLS &&
          !visited.has(key(nr, nc))
        ) {
          choices.push({ direction, r: nr, c: nc });
        }
      }

      if (choices.length === 0) {
        stack.pop();
        continue;
      }

      const choice = choices[Math.floor(random() * choices.length)];
      grid[current.r][current.c][choice.direction.name] = false;
      grid[choice.r][choice.c][choice.direction.opposite] = false;
      visited.add(key(choice.r, choice.c));
      stack.push({ r: choice.r, c: choice.c });
    }
  }

  function createBots(random) {
    const orders = shuffled(allDirectionOrders(), random);
    GAME.bots = [];

    for (let i = 0; i < BOT_COUNT; i++) {
      const start = { r: GAME.spawn.r, c: GAME.spawn.c };
      const bot = {
        path: [start],
        deadEnds: [],
        finishTick: null,

        r: start.r,
        c: start.c,
        color: "hsl(" + Math.round((i * 360) / BOT_COUNT) + " 82% 52%)",
        order: orders[i],
        knownCells: new Set([key(start.r, start.c)]),
        deadCellKeys: new Set(),
        stack: [start],
        previousR: start.r,
        previousC: start.c,
        motionStartedAt: performance.now()
      };
      GAME.bots.push(bot);
    }
  }

  function reset(seed) {
    activeSeed = normalizeSeed(seed);
    const random = makeRandom(activeSeed);

    GAME.elapsed = 0;
    GAME.size = { rows: ROWS, cols: COLS };
    GAME.spawn = { r: 0, c: 0 };
    GAME.exit = { r: ROWS - 1, c: COLS - 1 };

    generatePerfectMaze(random);
    createBots(random);
    updateHud();
    render();
    return GAME;
  }

  function wallsAt(r, c) {
    if (!Number.isInteger(r) || !Number.isInteger(c) ||
        r < 0 || r >= ROWS || c < 0 || c >= COLS) {
      return null;
    }
    const cell = grid[r][c];
    return { n: cell.n, e: cell.e, s: cell.s, w: cell.w };
  }

  function directionByName(name) {
    for (const direction of DIRECTIONS) {
      if (direction.name === name) return direction;
    }
    return null;
  }

  function moveBot(bot, r, c) {
    bot.previousR = bot.r;
    bot.previousC = bot.c;
    bot.r = r;
    bot.c = c;
    bot.motionStartedAt = performance.now();
    bot.path.push({ r: r, c: c });
  }

  function markDead(bot, r, c) {
    const cellKey = key(r, c);
    if (!bot.deadCellKeys.has(cellKey)) {
      bot.deadCellKeys.add(cellKey);
      bot.deadEnds.push({ r: r, c: c });
    }
  }

  function botStep(bot) {
    if (bot.finishTick !== null) return;

    const currentWalls = grid[bot.r][bot.c];

    for (const name of bot.order) {
      const direction = directionByName(name);

      /*
        This is the only maze lookup a bot makes: the walls of its current
        cell, learned on arrival. It never searches unseen cells globally.
      */
      if (currentWalls[name]) continue;

      const nr = bot.r + direction.dr;
      const nc = bot.c + direction.dc;
      const neighborKey = key(nr, nc);

      if (!bot.knownCells.has(neighborKey)) {
        bot.knownCells.add(neighborKey);
        bot.stack.push({ r: nr, c: nc });
        moveBot(bot, nr, nc);

        if (nr === GAME.exit.r && nc === GAME.exit.c) {
          bot.finishTick = GAME.elapsed;
        }
        return;
      }
    }

    /*
      Every reachable unexplored branch from this cell has now been tried.
      In a perfect maze the stack parent is the sole route back, so this edge
      is traversed a second and final time.
    */
    if (bot.stack.length > 1) {
      markDead(bot, bot.r, bot.c);
      bot.stack.pop();
      const parent = bot.stack[bot.stack.length - 1];
      moveBot(bot, parent.r, parent.c);
    }
  }

  function allFinished() {
    for (const bot of GAME.bots) {
      if (bot.finishTick === null) return false;
    }
    return true;
  }

  function tick(count) {
    let n = Math.max(0, Math.floor(Number(count) || 0));

    while (n > 0 && !allFinished()) {
      GAME.elapsed++;

      for (const bot of GAME.bots) {
        botStep(bot);
      }

      n--;
    }

    updateHud();
    render();
    return GAME.elapsed;
  }

  function updateHud() {
    let completed = 0;
    for (const bot of GAME.bots) {
      if (bot.finishTick !== null) completed++;
    }

    completedElement.textContent = "Completed: " + completed + " / " + BOT_COUNT;
    timerElement.textContent = "Timer: " + GAME.elapsed + " ticks" +
      (completed === BOT_COUNT ? " (frozen)" : "");
  }

  function drawWalls() {
    ctx.strokeStyle = "#16233a";
    ctx.lineWidth = 3;
    ctx.lineCap = "square";
    ctx.beginPath();

    for (let r = 0; r < ROWS; r++) {
      for (let c = 0; c < COLS; c++) {
        const x = c * CELL;
        const y = r * CELL;
        const wall = grid[r][c];

        if (wall.n) {
          ctx.moveTo(x, y);
          ctx.lineTo(x + CELL, y);
        }
        if (wall.w) {
          ctx.moveTo(x, y);
          ctx.lineTo(x, y + CELL);
        }
        if (r === ROWS - 1 && wall.s) {
          ctx.moveTo(x, y + CELL);
          ctx.lineTo(x + CELL, y + CELL);
        }
        if (c === COLS - 1 && wall.e) {
          ctx.moveTo(x + CELL, y);
          ctx.lineTo(x + CELL, y + CELL);
        }
      }
    }
    ctx.stroke();
  }

  function drawMarker(r, c, color, label) {
    const x = c * CELL;
    const y = r * CELL;

    ctx.fillStyle = color;
    ctx.fillRect(x + 7, y + 7, CELL - 14, CELL - 14);

    ctx.fillStyle = "#fff";
    ctx.font = "bold 12px Arial";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    ctx.fillText(label, x + CELL / 2, y + CELL / 2 + 1);
  }

  function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = "#f5f8ff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    const sx = GAME.spawn.c * CELL;
    const sy = GAME.spawn.r * CELL;
    ctx.fillStyle = "#dce7ff";
    ctx.fillRect(sx + 3, sy + 3, CELL - 6, CELL - 6);

    drawMarker(GAME.exit.r, GAME.exit.c, "#20ad61", "E");
    drawWalls();

    const now = performance.now();

    for (const bot of GAME.bots) {
      let progress = (now - bot.motionStartedAt) / (TICK_MS * 0.92);
      progress = Math.max(0, Math.min(1, progress));

      const drawR = bot.previousR + (bot.r - bot.previousR) * progress;
      const drawC = bot.previousC + (bot.c - bot.previousC) * progress;
      const x = (drawC + 0.5) * CELL;
      const y = (drawR + 0.5) * CELL;

      ctx.beginPath();
      ctx.arc(x, y, 5.3, 0, Math.PI * 2);
      ctx.fillStyle = bot.color;
      ctx.fill();

      ctx.lineWidth = 1.2;
      ctx.strokeStyle = "#07101c";
      ctx.stroke();
    }
  }

  function animationLoop(time) {
    lastFrameTime = time;
    render();
    requestAnimationFrame(animationLoop);
  }

  resetButton.addEventListener("click", function () {
    GAME.reset();
  });

  window.game = GAME;

  reset(123456789);
  requestAnimationFrame(animationLoop);

  setInterval(function () {
    if (!allFinished()) {
      GAME.tick(1);
    }
  }, TICK_MS);
})();
</script>
</body>
</html>
